/**
 * Lune's standard library, as Lune 0.10.5 defines it.
 *
 * Generated by `scripts/build-lune.mjs` from the `types.d.luau` files that
 * ship with `lune-org/lune` at `v0.10.5`, which is the API surface the runtime
 * is built against rather than a description of it. Do not edit by hand: run
 * `npm run build:lune` and read the diff.
 *
 * 61 functions across 10 modules.
 */

export interface LuneParam {
	name: string;
	/** The Luau type as the typedef writes it, verbatim. */
	type: string;
	optional: boolean;
	/** Lune's own `@param` line, where it has one. */
	what: string;
}

export interface LuneFunction {
	name: string;
	params: LuneParam[];
	/** The return type verbatim, or `""` when it returns nothing. */
	returns: string;
	/** Lune's own `@return` line. */
	returnsWhat: string;
	/**
	 * Lune tags it `must_use`: the point of the call is the value.
	 *
	 * Which is the line Roswaal draws between a pure node and one on the
	 * execution chain, so this decides that rather than being re-derived.
	 */
	mustUse: boolean;
	summary: string;
	/** The rest of the doc block — when it throws, and what it does not do. */
	detail: string;
}

export interface LuneClass {
	/** The type as the typedef names it: `Regex`, `DateTime`. */
	name: string;
	methods: LuneFunction[];
}

export interface LuneModule {
	/** The alias it is required under, without the `@lune/`. */
	alias: string;
	what: string;
	functions: LuneFunction[];
	/**
	 * The types this module hands back, and what they can be asked.
	 *
	 * Apart from `functions` because they are not called on the module:
	 * `regex.new` gives you a `Regex`, and its `find` is a method on that
	 * value. One flat list would offer a call nobody can make.
	 */
	classes: LuneClass[];
}

